    "clinicalCase": "Um homem com 37 anos, em situação de rua de longa data, com condições precárias de higiene pessoal, história de uso abusivo de álcool e de crack, procura atendimento em unidade de pronto atendimento devido a quadro de febre baixa intermitente não aferida, tosse produtiva com escarro esverdeado com rajas de sangue e odor fétido, fraqueza geral e emagrecimento. Ele refere que o quadro tem cerca de 3 semanas de evolução. Realizados os exames, o teste rápido molecular apresenta-se com resultado não detectável para micobactéria e o resultado da radiografia simples do tórax está reproduzida na imagem a seguir. O paciente é, então, encaminhado para internação hospitalar, sendo iniciado esquema antimicrobiano com Ceftriaxona e Metronidazol por via endovenosa. Após 20 dias de tratamento, o paciente mantém episódios de febre baixa intermitente, mas com menor intensidade, e refere persistirem os sintomas inicialmente descritos, exceto pela redução da hemoptise. Realizada nova radiografia simples de tórax, constata-se que a imagem mostra manutenção das alterações iniciais. A conduta recomendada nesse caso é",
