    "clinicalCase": "Uma paciente com 70 anos, menopausa ocorrida aos 52 anos, queixa-se de sangramento vaginal de pequena quantidade e intermitente, com 3 meses de evolução. Não tem história prévia de doença neoplásica pré-invasiva e teve dois citopatológicos negativos consecutivos dos 59 até os 64 anos. O exame especular realizado na última consulta não demonstrou lesões aparentes. Está acompanhada pela filha, que afirma estar muito ansiosa, porque leu casos parecidos relatados na internet e acha que a mãe pode estar com \"câncer de útero\". A paciente é tabagista (1 maço/dia), há 40 anos, e apresenta história mórbida pregressa de hipertensão arterial sistêmica, em tratamento, e de intolerância glicêmica, em tratamento, via oral. Conta que pratica pilates 3 vezes por semana e que tem independência financeira e social, apresentando-se calma durante a consulta. Ao exame físico, encontra-se lúcida, orientada, contactuante e atenta. Seu IMC é de 30 kg/m². Os exames laboratoriais não apresentam particularidades. Informa que gostaria de decidir sobre sua saúde por conta própria. Considerando esse caso, o médico generalista da atenção primária deve",
