    "clinicalCase": "Um homem com 40 anos, apresentando queixa de perda constante de interesse e de prazer nas atividades das quais costumava gostar, relata: “não tenho vontade sequer de sair de casa”. Afirma que isso vem se mantendo nos últimos 2 meses, de forma constante e diária, mas que piorou no último mês. Conta que seus amigos e familiares também perceberam e vêm cobrando dele uma mudança de atitude. Além disso, diz que tem se sentido mais ansioso e inquieto e que apresentou 2 “crises” súbitas, há um mês, de duração de alguns minutos, em que sentiu medo intenso, taquicardia, sufocação, tontura, sudorese e sensação de que algo ruim iria acontecer e de que iria morrer. Não relaciona as crises a fatores desencadeantes ou a situações pelas quais esteja passando. Relata que, quando teve as crises, foi a um pronto-socorro, onde foram descartadas causas orgânicas para o quadro. Refere também que apresentou perda de peso considerável no último mês, mas não sabe de quanto, tendo percebido apenas por suas roupas. Diz ainda que está sem fome e que tem tido muito sono todos os dias e se sente sempre cansado, está sem concentração e tem dificuldade de pensar. Nega etilismo, tabagismo ou uso de drogas ilícitas, negando também doenças conhecidas. Ao exame físico, o paciente apresenta-se sem alterações, assim como não mostram alterações os exames recentes de hemograma, TSH, T4 livre que ele traz. Ao exame psíquico, apresenta-se colaborativo, atenção preservada, com memória e orientação sem alterações; humor deprimido e ansioso; pensamento de forma, curso e conteúdo sem alterações, assim como juízo e crítica. Não se verificam alterações senso perceptivas, observando-se discreta agitação psicomotora. Considerando-se a situação descrita, qual é diagnóstico para o caso desse paciente?",
