    "clinicalCase": "Uma mulher com 25 anos, primigesta, na 39ª semana de gestação, encontra-se na segunda fase do trabalho de parto (colo totalmente dilatado, cabeça fletida, encaixada no plano +2 de De Lee, posição occipto-púbica, proporção cefalopélvica adequada), em bloco obstétrico de uma maternidade do Sistema Único de Saúde, atendida por equipe experiente. A gestante, segundo relatou, havia planejado parto normal em seu pré-natal, mas após uma hora de trabalho de parto, entra em exaustão, e as contrações uterinas vão diminuindo em frequência, mesmo depois de medidas encorajadoras de esforço. Realiza-se anestesia neuroaxial, é administrada ocitocina, sendo realizada amniotomia, que revelou líquido meconial. A cardiotocografia apresenta resultado normal, razão pela qual a equipe médica decide aguardar a progressão do parto, porém, com 2 horas e meia de trabalho de parto, nova cardiotocografia aponta bradicardia, e as contrações não se revelam eficientes para a conclusão do período expulsivo. A partir do caso clínico descrito, qual deve ser a melhor conduta?",
