    "subtopic": "",
    "clinicalCase": "Um recém-nascido, com peso de nascimento de 2.900 g, nascido a termo e de parto vaginal, é levado à primeira consulta pós-natal na unidade básica de saúde com 10 dias de vida. Durante a consulta, observa-se abundante quantidade de secreção purulenta em ambos os olhos da criança e, segundo a mãe, essa secreção teve início há 2 dias, formando-se rapidamente, mesmo após a limpeza. O paciente apresenta, também, hiperemia ocular e edema bipalpebral. Sabe-se que a mãe iniciou tardiamente o pré-natal e fez acompanhamento irregular, e ela refere que, atualmente, está apresentando leucorreia purulenta. O médico, então, solicita swab da secreção, cujo resultado chegará em até 5 dias. Com base nessas informações, quais são, respectivamente, o diagnóstico da doença da criança e a conduta médica adequada para o caso?",
